# mindsensors AbsoluteIMU con el driver ms-absolute-imu de ev3dev.
# Modo GYRO: value0..2 = X, Y, Z; con decimals = 1 el entero viene por diez.
# Medido en el robot: girando a la derecha, Z acumula positivo.
ABSIMU_SYSFS = "/sys/class/"
ABSIMU_PUERTOS = {Port.S1: "in1", Port.S2: "in2", Port.S3: "in3", Port.S4: "in4"}
ABSIMU_ZONA_MUERTA = 0.3
absimu_sensores = {}


def absimu_leer_texto(ruta):
    with open(ruta) as archivo:
        return archivo.read().strip()


def absimu_escribir(ruta, texto):
    with open(ruta, "w") as archivo:
        archivo.write(texto)


def absimu_es_imu(puerto):
    try:
        sensor = Ev3devSensor(puerto)
        ruta = ABSIMU_SYSFS + "lego-sensor/sensor%d/driver_name" % sensor.sensor_index
        return absimu_leer_texto(ruta) == "ms-absolute-imu"
    except OSError:
        return False


def absimu_configurar_puerto(puerto):
    # El EV3 solo detecta los sensores I2C NXT en 0x01; el AbsoluteIMU está en 0x11.
    direccion = "ev3-ports:" + ABSIMU_PUERTOS[puerto]
    for indice in range(16):
        ruta = ABSIMU_SYSFS + "lego-port/port%d/" % indice
        try:
            if absimu_leer_texto(ruta + "address") != direccion:
                continue
            if absimu_leer_texto(ruta + "mode") != "nxt-i2c":
                absimu_escribir(ruta + "mode", "nxt-i2c")
                wait(500)
            absimu_escribir(ruta + "set_device", "ms-absolute-imu 0x11")
            wait(500)
        except OSError:
            pass
        return


class AbsImu:
    def __init__(self, sensor):
        ruta = ABSIMU_SYSFS + "lego-sensor/sensor%d/" % sensor.sensor_index
        # El driver arranca en COMPASS.
        if absimu_leer_texto(ruta + "mode") != "GYRO":
            absimu_escribir(ruta + "mode", "GYRO")
        self.escala = 1 / 10 ** int(absimu_leer_texto(ruta + "decimals"))
        self.ruta = ruta + "value2"
        self.archivo = None
        self.candado = _thread.allocate_lock()
        self.cero = 0.0
        self.angulo = 0.0
        self.velocidad = 0.0
        self.suma = 0.0
        self.cuenta = 0
        self.pedidas = 0
        # Primera lectura aquí: la velocidad vale desde el primer bloque.
        velocidad = self.leer()
        if abs(velocidad) >= ABSIMU_ZONA_MUERTA:
            self.velocidad = velocidad
        _thread.start_new_thread(self.integrar, ())

    def leer(self):
        try:
            if self.archivo is None:
                self.archivo = open(self.ruta)
            self.archivo.seek(0)
            return int(self.archivo.read()) * self.escala
        except (OSError, ValueError):
            self.archivo = None
            raise OSError("el AbsoluteIMU no responde")

    def integrar(self):
        # Hilo propio: integra Z cada 10 ms aunque el programa esté esperando.
        reloj = StopWatch()
        antes = reloj.time()
        previa = self.velocidad
        while True:
            try:
                cruda = self.leer()
            except OSError:
                wait(20)
                continue
            ahora = reloj.time()
            self.candado.acquire()
            if self.pedidas:
                self.suma += cruda
                self.cuenta += 1
                if self.cuenta >= self.pedidas:
                    self.cero = self.suma / self.cuenta
                    self.angulo = previa = self.velocidad = 0.0
                    self.pedidas = 0
            else:
                velocidad = cruda - self.cero
                if abs(velocidad) < ABSIMU_ZONA_MUERTA:
                    velocidad = 0.0
                self.angulo += (velocidad + previa) * (ahora - antes) / 2000
                self.velocidad = previa = velocidad
            self.candado.release()
            antes = ahora
            wait(2 if self.pedidas else 10)


def absimu(puerto, bloque):
    if puerto not in absimu_sensores:
        if not absimu_es_imu(puerto):
            absimu_configurar_puerto(puerto)
            for intento in range(20):
                if absimu_es_imu(puerto):
                    break
                wait(100)
        sensor = rb_device(puerto, Ev3devSensor, bloque)
        try:
            absimu_sensores[puerto] = AbsImu(sensor)
        except (OSError, ValueError):
            rb_fail(bloque, "No responde el AbsoluteIMU de mindsensors (0x11)")
    return absimu_sensores[puerto]


def absimu_calibrar(imu, muestras):
    imu.candado.acquire()
    imu.suma, imu.cuenta, imu.pedidas = 0.0, 0, max(1, int(muestras))
    imu.candado.release()
    reloj = StopWatch()
    while imu.pedidas:
        if reloj.time() > 2000 + 20 * muestras:
            imu.pedidas = 0
            raise OSError("el AbsoluteIMU no responde")
        wait(10)


def absimu_reiniciar(puerto, angulo, bloque):
    imu = absimu(puerto, bloque)
    imu.candado.acquire()
    imu.angulo = float(angulo)
    imu.candado.release()


def absimu_angulo(puerto, bloque):
    return round(absimu(puerto, bloque).angulo, 1)


def absimu_velocidad(puerto, bloque):
    return round(absimu(puerto, bloque).velocidad, 1)

